H('50.c.2.B',3,"Supporting details in a text are used to:","back up the main idea",["replace the title","end the story","hide the theme"],"Details support the central point.")
H('50.c.2.C',4,"Studying how a poet uses imagery and sound effects is analysis of:","literary devices",["tax records","road maps","weather charts"],"Literary devices shape meaning and style.")
H('50.c.2.C',4,"Epic, satire and elegy are examples of:","genres",["verb endings","coins","calendars"],"Genre is a category of literature.")
H('50.c.2.D',3,"If a word in a classical text is unfamiliar, a reader can infer its meaning from:","the surrounding words and context",["its font size","the page number","the book price"],"Context clues reveal meaning.")
H('50.c.2.D',3,"Recognizing a familiar root inside an unknown word helps you to:","guess its likely meaning",["skip the sentence","change the author","delete the passage"],"Roots carry meaning across related words.")
