# ===== 114.52 Seminar in Classical Languages =====
H('52.c.1.A',3,"A good researchable question is one that:","can be investigated with available sources",["has no possible answer","is already solved","needs no evidence"],"Researchable questions can be answered through evidence.")
H('52.c.1.A',3,"In a seminar, topic questions are approved by:","the instructor",["a stranger","no one","the library door"],"The instructor guides and approves research questions.")
H('52.c.1.B',3,"Communicating with clarity in a seminar discussion means:","expressing ideas so others can follow them",["speaking as quickly as possible","using unclear terms","avoiding all questions"],"Clear communication supports full participation.")
H('52.c.1.B',3,"Participating fully in a seminar includes:","listening, responding and contributing",["only taking notes","staying silent","leaving early"],"Participation is active.")
